public class ReverseArray {
    public static void main(String[] args) {
        int[] arr = {10,20,30,40,50,60,70};
        int i =0;
        for(i = arr.length-1 ;i>=0 ;i--){
            System.out.println(  " reverse array :"+ arr[i]);
        }
      //  System.out.println(  " reverse array :"+ arr[i]);
    }
    
}
